const sample = (n: number) => `0a000000-0000-4000-8000-00000000000${n}`;

const health = (elapsedSeconds: number, producer: 'phone' | 'watch', producerSequence: number, values: Row): Row => ({
  elapsedSeconds,
  timestamp: `2026-05-01T07:30:${String(elapsedSeconds).padStart(2, '0')}.000Z`,
  producer,
  producerSequence,
  clockEpoch: producer === 'watch' ? 'hw-1' : 'hp-1',
  ...values,
});

const reading = (elapsedSeconds: number, producerSequence: number, connection: string | null, humanPowerW: number) => ({
  elapsedSeconds,
  timestamp: `2026-05-01T07:30:0${elapsedSeconds}.000Z`,
  producerSequence,
  clockEpoch: 'cyc-1',
  connection,
  humanPowerW,
});

const event = (elapsedSeconds: number, producerSequence: number, action: string, timerSeconds: number) => ({
  elapsedSeconds,
  timestamp: `2026-05-01T07:30:${String(elapsedSeconds).padStart(2, '0')}.000Z`,
  producer: 'watch',
  producerSequence,
  clockEpoch: 'hw-1',
  action,
  timerSeconds,
  interrupted: 0,
});

